async function sget(key) {
  if (key.startsWith('exam:')) {
    const code = key.split(':')[1];
    try {
      let r = await fetch(`${SCRIPT_URL}?action=getExam&code=${code}`);
      let text = await r.text();
      if(text.trim().startsWith('<!DOCTYPE') || text.trim().startsWith('<html')) {
         alert("গুগল স্ক্রিপ্ট সমস্যা: স্ক্রিপ্টটি সঠিকভাবে ডেপ্লয় করা হয়নি অথবা 'Anyone' অ্যাক্সেস দেওয়া হয়নি।");
         return null;
      }
      let json = JSON.parse(text);
      if (json.status === "success") {
        localStorage.setItem(key, JSON.stringify(json.data));
        return { value: JSON.stringify(json.data) };
      }
    } catch(e) {
      alert("নেটওয়ার্ক বা গুগলের সমস্যা: " + e.message);
    }
  }
  const r = localStorage.getItem(key);
  return r ? { value: r } : null;
}

async function sset(key, value) {
  localStorage.setItem(key, value);
  try {
    if (key.startsWith('exam:')) {
      const code = key.split(':')[1];
      const r = await fetch(SCRIPT_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' }, // avoids CORS preflight; Apps Script just reads raw body
        body: JSON.stringify({ action: 'saveExam', code, exam: value })
      });
      const text = await r.text();
      let json;
      try { json = JSON.parse(text); } catch(parseErr){
        console.error('saveExam: non-JSON response', text);
        toast('সেভ ব্যর্থ: সার্ভার থেকে ভুল উত্তর এসেছে');
        return null;
      }
      if(json.status !== 'success'){
        console.error('saveExam failed', json);
        toast('সেভ ব্যর্থ: ' + (json.message || 'অজানা সমস্যা'));
        return null;
      }
    } else if (key.startsWith('result:')) {
      const parts = key.split(':');
      const code = parts[1];
      const slug = parts[2];
      const r = await fetch(SCRIPT_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'submitResult', code, slug, result: value })
      });
      const text = await r.text();
      let json;
      try { json = JSON.parse(text); } catch(parseErr){
        console.error('submitResult: non-JSON response', text);
        toast('জমা ব্যর্থ: সার্ভার থেকে ভুল উত্তর এসেছে');
        return null;
      }
      if(json.status !== 'success'){
        console.error('submitResult failed', json);
        toast('জমা ব্যর্থ: ' + (json.message || 'অজানা সমস্যা'));
        return null;
      }
    }
    return true;
  } catch(e) {
    console.error('sset network error', e);
    toast('নেটওয়ার্ক সমস্যা: সেভ/জমা করা যায়নি');
    return null;
  }
}

async function sdel(key){ localStorage.removeItem(key); return true; }
async function slist(prefix){
  const keys = [];
  for (let i = 0; i < localStorage.length; i++) {
    const k = localStorage.key(i);
    if (k.startsWith(prefix)) keys.push(k);
  }
  return keys;
}

async function getRemoteResults(code) {
  try {
    let r = await fetch(`${SCRIPT_URL}?action=getResults&code=${code}`);
    let json = await r.json();
    if (json.status === "success") return json.data;
  } catch(e){}
  return [];
}

function renderAllMath(elem){
  const target = elem || document.getElementById('app') || document.body;
  if(window.renderMathInElement && target){
    try{
      renderMathInElement(target, {
        delimiters: [
          { left: '$$', right: '$$', display: true },
          { left: '$', right: '$', display: false },
          { left: '\\(', right: '\\)', display: false },
          { left: '\\[', right: '\\]', display: true }
        ],
        ignoredTags: ['script', 'noscript', 'style', 'textarea', 'pre', 'code'],
        throwOnError: false
      });
    }catch(e){
      console.warn('KaTeX render error:', e);
    }
  }
}

// ================= PWA INSTALLATION & SERVICE WORKER =================
let deferredPwaPrompt = null;
window.addEventListener('beforeinstallprompt', (e) => {
  e.preventDefault();
  deferredPwaPrompt = e;
  document.querySelectorAll('.pwa-install-banner').forEach(el => el.style.display = 'flex');
  const hBtn = document.getElementById('headerInstallBtn');
  if(hBtn) hBtn.style.display = 'inline-flex';
});

window.installPwa = async function(){
  if(deferredPwaPrompt){
    deferredPwaPrompt.prompt();
    const { outcome } = await deferredPwaPrompt.userChoice;
    if(outcome === 'accepted'){
      toast('অ্যাপ সফলভাবে ইনস্টল হয়েছে! 🎉');
      document.querySelectorAll('.pwa-install-banner').forEach(el => el.style.display = 'none');
      const hBtn = document.getElementById('headerInstallBtn');
      if(hBtn) hBtn.style.display = 'none';
    }
    deferredPwaPrompt = null;
    return;
  }
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
  if(isIOS){
    if(typeof showIosInstallGuide === 'function') showIosInstallGuide();
    else toast('Safari ব্রাউজারের নিচে Share বাটন চেপে Add to Home Screen করুন');
  } else {
    toast('ইনস্টল করতে ব্রাউজারের থ্রি-ডট (⋮) মেন্যু থেকে "Install app" বা "Add to Home Screen" চাপুন');
  }
};

