// ================= VOICE DOUBT & SPEECH SYNTHESIS =================
let recognition = null;
let isRecordingVoice = false;

window.toggleVoiceInput = function(){
  const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
  if(!SpeechRec){
    toast('আপনার ব্রাউজারে ভয়েস টাইপিং সাপোর্ট নেই (Google Chrome ব্যবহার করুন)');
    return;
  }
  const btn = document.getElementById('voiceInputBtn');
  const txtArea = document.getElementById('doubtText');
  if(!txtArea) return;

  if(isRecordingVoice && recognition){
    recognition.stop();
    isRecordingVoice = false;
    if(btn){
      btn.classList.remove('recording');
      btn.innerHTML = '🎙️ মুখে বলো (বাংলায়)';
    }
    return;
  }

  try{
    recognition = new SpeechRec();
    recognition.lang = 'bn-BD';
    recognition.continuous = false;
    recognition.interimResults = false;

    recognition.onstart = function(){
      isRecordingVoice = true;
      if(btn){
        btn.classList.add('recording');
        btn.innerHTML = '🔴 শুনছি... কথা বলুন';
      }
      toast('কথা বলুন (বাংলায়)...');
    };

    recognition.onresult = function(event){
      if(event.results && event.results[0] && event.results[0][0]){
        const transcript = event.results[0][0].transcript;
        if(transcript){
          txtArea.value = (txtArea.value ? txtArea.value + ' ' : '') + transcript;
          toast('ভয়েস যুক্ত হয়েছে!');
        }
      }
    };

    recognition.onerror = function(event){
      console.warn('SpeechRec error:', event.error);
      isRecordingVoice = false;
      if(btn){
        btn.classList.remove('recording');
        btn.innerHTML = '🎙️ মুখে বলো (বাংলায়)';
      }
      if(event.error === 'not-allowed'){
        toast('মাইক্রোফোন পারমিশন দেওয়া হয়নি');
      } else {
        toast('ভয়েস বুঝতে সমস্যা হয়েছে, আবার চেষ্টা করো');
      }
    };

    recognition.onend = function(){
      isRecordingVoice = false;
      if(btn){
        btn.classList.remove('recording');
        btn.innerHTML = '🎙️ মুখে বলো (বাংলায়)';
      }
    };

    recognition.start();
  }catch(err){
    console.error('Speech recognition error:', err);
    isRecordingVoice = false;
    if(btn){
      btn.classList.remove('recording');
      btn.innerHTML = '🎙️ মুখে বলো (বাংলায়)';
    }
  }
};

window.toggleReadAloud = function(text){
  if(!('speechSynthesis' in window)){
    toast('আপনার ব্রাউজারে স্পিচ সুবিধা নেই');
    return;
  }
  if(window.speechSynthesis.speaking){
    window.speechSynthesis.cancel();
    toast('পড়া থামানো হয়েছে');
    return;
  }
  const cleanText = (text || '').replace(/<[^>]*>/g, '').replace(/[*_#`$]/g, '').trim();
  if(!cleanText) return;

  const utter = new SpeechSynthesisUtterance(cleanText);
  const voices = window.speechSynthesis.getVoices();
  const bnVoice = voices.find(v => v.lang && v.lang.toLowerCase().includes('bn'));
  if(bnVoice) utter.voice = bnVoice;
  utter.rate = 0.95;

  utter.onend = () => { toast('পড়া শেষ হয়েছে'); };
  utter.onerror = () => { toast('পড়তে সমস্যা হয়েছে'); };

  window.speechSynthesis.speak(utter);
  toast('🔊 উত্তর পড়ে শোনানো হচ্ছে...');
};

function genCode(){ const chars = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; let c=''; for(let i=0;i<5;i++) c += chars[Math.floor(Math.random()*chars.length)]; return c; }
function genId(prefix){ return prefix + '_' + Date.now() + '_' + Math.floor(Math.random()*10000); }
function slugify(name){ return name.trim().toLowerCase().replace(/[^a-z0-9\u0980-\u09FF]+/g,'_').slice(0,40) || 'student'; }
function escapeHtml(s){ return (s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function linkifyText(s){
  const escaped = escapeHtml(s);
  return escaped.replace(/(https?:\/\/[^\s<]+)/g, url => `<a href="${url}" target="_blank" rel="noopener" style="color:var(--margin-red); text-decoration:underline;">${url}</a>`);
}
async function postToScript(action, params){
  try{
    const r = await fetch(SCRIPT_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' }, // avoids CORS preflight; Apps Script reads raw body
      body: JSON.stringify({ action, ...params })
    });
    const text = await r.text();
    let json;
    try{ json = JSON.parse(text); } catch(parseErr){
      console.error(action+': non-JSON response', text);
      toast('সেভ ব্যর্থ: সার্ভার থেকে ভুল উত্তর এসেছে');
      return null;
    }
    if(json.status !== 'success'){
      console.error(action+' failed', json);
      toast('ব্যর্থ: ' + (json.message || 'অজানা সমস্যা'));
      return null;
    }
    return json;
  } catch(e){
    console.error(action+' network error', e);
    toast('নেটওয়ার্ক সমস্যা: আবার চেষ্টা করো');
    return null;
  }
}
function formatDate(v){ if(!v) return ''; const d = new Date(v); return isNaN(d.getTime()) ? String(v) : d.toLocaleString('bn-BD'); }
function fmtTime(totalSec){ const m = Math.floor(totalSec/60), s = totalSec%60; return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0'); }

