  if(typeof closeLibraryPanel==='function') closeLibraryPanel();
  // ড্যাশবোর্ডে ঢোকার সময় সবসময় নতুন ডাটা আনো (নাহলে পরীক্ষা দিয়ে কুপন পেলেও পুরনো ব্যালেন্স দেখাত)
