window.landingHubState = window.landingHubState || { study: true, exam: false, community: false, rewards: false };

window.toggleLandingHub = function(hubId){
  if(!window.landingHubState) window.landingHubState = { study: true, exam: false, community: false, rewards: false };
  window.landingHubState[hubId] = !window.landingHubState[hubId];
  const folder = document.getElementById('hub_folder_' + hubId);
  const body = document.getElementById('hub_body_' + hubId);
  if(folder && body){
    if(window.landingHubState[hubId]){
      folder.classList.add('open');
      body.style.display = 'block';
    } else {
      folder.classList.remove('open');
      body.style.display = 'none';
    }
  }
};

window.toggleAllLandingHubs = function(expand){
  if(!window.landingHubState) window.landingHubState = {};
  const hubs = ['study', 'exam', 'community', 'rewards'];
  hubs.forEach(h => {
    window.landingHubState[h] = expand;
    const folder = document.getElementById('hub_folder_' + h);
    const body = document.getElementById('hub_body_' + h);
    if(folder && body){
      if(expand){
        folder.classList.add('open');
        body.style.display = 'block';
      } else {
        folder.classList.remove('open');
        body.style.display = 'none';
      }
    }
  });
};

